using System.IO;
using System.Diagnostics;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using Microsoft.Win32;

namespace Hatrack;
public sealed class EditorWindow : Window
{
    private readonly List<Installation> installs;private readonly Profile? existing;private readonly DiscoveredProfile? imported;
    private readonly ComboBox app=new(){ItemsSource=Enum.GetValues<DesktopApp>(),SelectedIndex=0,MinHeight=40};
    private readonly TextBox name=new(){MinHeight=40},color=new(){Text="#D97757",MinHeight=40};
    private readonly ComboBox shape=new(){ItemsSource=Icons.Shapes,SelectedIndex=0,MinHeight=40};
    private readonly ComboBox background=new(){ItemsSource=new[]{"Transparent","#FFFFFF","#171717"},SelectedIndex=0,MinHeight=40};
    private readonly CheckBox desktop=new(){Content="Desktop shortcut",IsChecked=true},start=new(){Content="Start Menu shortcut",IsChecked=true},favorite=new(){Content="Favourite",IsChecked=false};
    private readonly StackPanel dependencyActions=new(){Orientation=Orientation.Horizontal,Margin=new Thickness(0,8,0,12)};
